  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the final booking price after evaluating membership discount eligibility.
   * Algorithm: If `customer` is null or `customer.membershipPackage` is null, return `roundTo1Decimal(this.price)`. If `!customer.membershipPackage.hasAward(Award.DISCOUNTS)`, return `roundTo1Decimal(this.price)`. Calculate the time difference between `bookingTime` and the trip's departure datetime (`departureDate` combined with `departureTime`). If `bookingTime` is at least 24 hours before departure, calculate `discountedPrice = this.price * 0.8`. Else, `discountedPrice = this.price`. Return `roundTo1Decimal(discountedPrice)`.
   * Related Features: price, departureTime, departureDate
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer, bookingTime : String (Format: "YYYY-MM-DDTHH:mm")
   * Output: double - Final price after discount, formatted to one decimal place.
   * Pre-condition: price, departureDate, and departureTime are valid. bookingTime is valid.
   * Post-condition: None.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null ||
        !customer.getMembershipPackage().hasAward(Award.DISCOUNTS))
    {
      return Math.round(this.getPrice() * 10.0) / 10.0;
    }

    DateTimeFormatter bookingFmt = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");
    LocalDateTime bookingLdt = LocalDateTime.parse(bookingTime, bookingFmt);

    LocalDate depDate = this.getDepartureDate().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDate();
    LocalDateTime depLdt = LocalDateTime.of(depDate, LocalTime.parse(this.getDepartureTime(), DateTimeFormatter.ofPattern("HH:mm")));

    double discountedPrice = ChronoUnit.HOURS.between(bookingLdt, depLdt) >= 24 ? this.getPrice() * 0.8 : this.getPrice();
    return Math.round(discountedPrice * 10.0) / 10.0;
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes reward points generated by bookings for this specific trip during a given month.
   * Algorithm: If customer is null or customer.membershipPackage is null, return 0. If !customer.membershipPackage.hasAward(Award.POINTS), return 0. Initialize points = 0. For each booking in this.bookings, if booking.isInMonth(currentMonth) returns true, add booking.numberOfSeats * 5 to points. Return points.
   * Related Features: bookings
   * Related Classes: Booking, Customer, MembershipPackage, Award
   * Input: customer : Customer, currentMonth : String (Format: "YYYY-MM")
   * Output: int - Points earned for this trip's bookings in the specified month.
   * Pre-condition: Bookings list and customer data are accessible.
   * Post-condition: None.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null ||
        !customer.getMembershipPackage().hasAward(Award.POINTS))
    {
      return 0;
    }

    int points = 0;
    for (Booking booking : this.getBookings())
    {
      if (booking.isInMonth(currentMonth))
      {
        points += booking.getNumberOfSeats() * 5;
      }
    }
    return points;
  }

